go.solution:
package main

import (
	"fmt"
	"strconv"
)

func doubleText(text string) (int, error) {
	number, err := strconv.Atoi(text)
	if err != nil {
		return 0, err
	}
	return number * 2, nil
}

func main() {
	var text string
	fmt.Scan(&text)
	doubled, err := doubleText(text)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(doubled)
}

